#include <stdio.h>

static int ishl(int a, int b) { return a << b; }

int main(void) {
  printf("%d\n", ishl(1, 4));
  printf("%d\n", ishl(3, 5));
  unsigned int u = 1u;
  printf("%u\n", u << 31);
  return 0;
}



